Ltac join_fr H1 H2 :=
        lazymatch type of H1 with rw_cells _ ?mm ?A ?cs1 => lazymatch type of H2 with rw_cells _ mm ?B ?cs2 =>
          let H := fresh "FRj" in
          assert (H : rw_cells asegs mm A (cs1 ++ cs2));
          [ apply (proj2 (rw_cells_app mm A cs1 cs2)); split; [exact H1 | replace (A + Z.of_nat (cells_size cs1)) with B; [exact H2 | cbn [cells_size csize Nat.add]; lia]] | ];
